let webhook = $json ?? {};
let input = webhook.body ?? webhook;
if (typeof input === 'string') { try { input = JSON.parse(input); } catch { input = {}; } }
const backgroundPrompt = typeof input.backgroundPrompt === 'string' ? input.backgroundPrompt.trim() : '';
const backgroundId = String(input.backgroundId || '');
const sceneNumbers = Array.isArray(input.sceneNumbers) ? input.sceneNumbers.map(Number).filter(Number.isFinite) : [];
const allowedOrigins = ["https://script-to-storyboard-six.vercel.app","https://script-to-storyboard-bczcrjyi8-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-rh9j2ogz2-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-rj8si3nam-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-2936gb8xd-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-git-codex-5b7cab-rayvin-gianan-s-projects.vercel.app"];
const requestMode = input.mode === 'single' || input.requestMode === 'single' ? 'single' : 'batch';
const requestedOrigin = String(webhook.headers?.origin || input.corsOrigin || '');
const corsOrigin = allowedOrigins.includes(requestedOrigin) ? requestedOrigin : allowedOrigins[0];
if (backgroundPrompt.length < 20 || backgroundPrompt.length > 2500 || !backgroundId || !sceneNumbers.length) return [{json:{ok:false,statusCode:422,backgroundId,sceneNumbers,backgroundPrompt,requestMode,corsOrigin,error:'A selected storyboard background with its scene identity is required.'}}];
const prompt = [
'Create ONE single continuous, full-frame landscape 16:9 environment background plate for this storyboard scene. The image must show one complete location across the entire canvas, edge to edge.',
'Match the approved reference image’s drawing treatment only: consistent hand-drawn 2D cartoon, bold slightly irregular black ink outlines, chunky simplified shapes, flat color fills, minimal shading, and clear readable forms. Never make it photorealistic or 3D.',
'Build the location, palette, and composition specifically from the scene Background description below. The reference image controls linework and color treatment only; do not copy its room, furniture, palette, layout, or camera composition unless the scene calls for them.',
'SHOW ONE ENVIRONMENT ONLY. Absolutely no split screen, triptych, panels, multi-panel layout, collage, inset, storyboard sheet, vertical or horizontal dividers, borders between scenes, alternate locations, or multiple views. This is one standalone full background image, not a set of panels.',
'Environment only: exclude people, characters, animals, faces, bodies, body parts, hands, movable foreground props, diagrams, symbols, lettering, captions, logos, watermarks, and motion marks. Fixed architecture and environmental set dressing may establish the location. Leave clear open space where animators can draw characters and props.',
'SINGLE SCENE BACKGROUND: ' + backgroundPrompt
].join(' ');
return [{json:{ok:true,fileId:'19_rZZhpt3du495njrjnO5nuPWQjxnMAQ',backgroundId,sceneNumbers,backgroundPrompt,prompt,requestMode,corsOrigin}}];

const request=$('Prepare Scene-Specific Image Prompt').item.json;
const file=$input.first();const binary=file.binary?.data;
if(!request.ok)return[{json:request}];
if(!binary||!String(binary.mimeType||'').startsWith('image/'))return[{json:{ok:false,statusCode:502,backgroundId:request.backgroundId,sceneNumbers:request.sceneNumbers,backgroundPrompt:request.backgroundPrompt,error:'The approved Google Drive style reference could not be loaded as an image.'}}];
try{const buffer=await this.helpers.getBinaryDataBuffer(0,'data');const mimeType=binary.mimeType||'image/png';const inputReference={type:'image_url',image_url:{url:'data:'+mimeType+';base64,'+buffer.toString('base64')}};
return[{json:{model:'openai/gpt-image-2.5-flare',prompt:request.prompt,n:1,aspect_ratio:'16:9',quality:'low',input_references:[inputReference],backgroundId:request.backgroundId,sceneNumbers:request.sceneNumbers,backgroundPrompt:request.backgroundPrompt}}];
}catch(error){return[{json:{ok:false,statusCode:502,backgroundId:request.backgroundId,sceneNumbers:request.sceneNumbers,backgroundPrompt:request.backgroundPrompt,error:'Could not read the approved Google Drive style reference: '+String(error?.message||error).slice(0,500)}}]}

const response=$json??{};
const request=$('Prepare Scene-Specific Image Prompt').item.json;
const identity={backgroundId:request.backgroundId,sceneNumbers:request.sceneNumbers,backgroundPrompt:request.backgroundPrompt,requestMode:request.requestMode,corsOrigin:request.corsOrigin};
if(response.ok===false&&response.error)return[{json:{...response,...identity,ok:false}}];
const body=response.body&&typeof response.body==='object'?response.body:response;
const image=body.data?.[0];const b64=image?.b64_json;
if(!b64){const providerError=body.error;const errorMessage=typeof providerError==='string'?providerError:providerError?.message||response.error?.message||body.message||'OpenRouter did not return image bytes.';const statusCode=Number(response.statusCode||providerError?.code||502);return[{json:{ok:false,statusCode,error:String(errorMessage).slice(0,1000),model:'openai/gpt-image-2.5-flare',...identity}}]}
const mimeType=image.media_type||body.media_type||'image/jpeg';
if(!mimeType.startsWith('image/'))return[{json:{ok:false,statusCode:502,error:'OpenRouter returned an unsupported media type.',model:'openai/gpt-image-2.5-flare',...identity}}];
return[{json:{ok:true,model:'openai/gpt-image-2.5-flare',...identity,mimeType,costUsd:body.usage?.cost??null,imageData:'data:'+mimeType+';base64,'+b64}}];

let webhook = $json ?? {};
let body = webhook.body ?? webhook;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const allowedOrigins = ["https://script-to-storyboard-six.vercel.app","https://script-to-storyboard-bczcrjyi8-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-rh9j2ogz2-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-rj8si3nam-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-2936gb8xd-rayvin-gianan-s-projects.vercel.app","https://script-to-storyboard-git-codex-5b7cab-rayvin-gianan-s-projects.vercel.app"];
const requestedOrigin = String(webhook.headers?.origin || body.origin || '');
const corsOrigin = allowedOrigins.includes(requestedOrigin) ? requestedOrigin : allowedOrigins[0];
const mode = body.mode === 'planOnly' ? 'planOnly' : 'batch';
const script = typeof body.script === 'string' ? body.script.trim() : '';
if (script.length < 20 || script.length > 30000) return [{json:{ok:false,statusCode:400,error:'Paste a script between 20 and 30,000 characters.',mode,corsOrigin}}];
const firstLine = script.split(/\r?\n/).map(part => part.trim()).find(Boolean) || '';
const title = String(body.title || firstLine.slice(0,120) || 'Untitled storyboard').trim().slice(0,120);
return [{json:{ok:true,title,script,mode,corsOrigin}}];

const req = $('Validate Full Script').first().json;
const rows = $('Read Planner Context').all().map(item => item.json);
const grouped = { styleGuide: [], referenceIndex: [], examples01: [], examples03: [] };

for (const row of rows) {
  const type = String(row.recordType || '');
  const raw = row.payloadJson;
  let payload;
  try { payload = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { continue; }
  if (!payload || typeof payload !== 'object') continue;
  if (type === 'style_guide') grouped.styleGuide.push(payload);
  else if (type === 'reference_index') grouped.referenceIndex.push(payload);
  else if (type === 'example_01') grouped.examples01.push(payload);
  else if (type === 'example_03') grouped.examples03.push(payload);
}

const stopWords = new Set(['about','after','again','also','because','been','being','could','does','from','have','into','just','more','most','that','their','them','then','there','these','they','this','those','through','very','what','when','where','which','while','with','would','your']);
const terms = new Set((req.script.toLowerCase().match(/[\p{L}\p{N}]+/gu) || []).filter(word => word.length > 3 && !stopWords.has(word)));
const rank = sourceRows => sourceRows.map((row, index) => {
  const text = JSON.stringify(row).toLowerCase();
  let score = 0;
  for (const term of terms) if (text.includes(term)) score += 1;
  return { row, score, index };
}).sort((a, b) => b.score - a.score || a.index - b.index).slice(0, 4).map(item => item.row);

const environmentReferences = grouped.referenceIndex.filter(row => String(row.referenceType || '').toLowerCase() === 'environment').slice(0, 2);
return [{ json: {
  title: req.title,
  script: req.script,
  styleGuide: grouped.styleGuide,
  referenceIndex: environmentReferences.length ? environmentReferences : grouped.referenceIndex.slice(0, 1),
  examples01: rank(grouped.examples01),
  examples03: rank(grouped.examples03)
} }];

const request = $('Validate Full Script').first().json;
const fail = (error, statusCode = 422) => [{ json: { ok: false, statusCode, error, mode: request.mode, corsOrigin: request.corsOrigin } }];
const raw = $json.output ?? $json;
if ($json.error) { const detail = typeof $json.error === 'string' ? $json.error : $json.error?.message || JSON.stringify($json.error); return fail('Storyboard generation failed: ' + String(detail).slice(0, 900), 502); }
let plan;
try { plan = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { return fail('The storyboard model returned invalid structured data. No images were generated.', 502); }
if (!Array.isArray(plan?.scenes) || !plan.scenes.length) return fail('The storyboard model returned no scenes. No images were generated.', 502);
if (!request.ok || typeof request.script !== 'string') return fail(request.error || 'The submitted script is invalid.', request.statusCode || 400);
const stripTimecodes = value => String(value || '').replace(/\b\d{1,2}:\d{2}(?::\d{2})?(?:\s*[-–—]\s*\d{1,2}:\d{2}(?::\d{2})?)?\b/g, ' ');
const tokens = value => String(value || '').normalize('NFKC').toLowerCase().match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu) || [];
const sourceTokens = tokens(stripTimecodes(request.script));
const voiceoverTokens = tokens(plan.scenes.map(scene => String(scene?.voiceover || '')).join(' '));
if (sourceTokens.length !== voiceoverTokens.length || !sourceTokens.every((token, index) => token === voiceoverTokens[index])) return fail('The storyboard did not preserve the complete script in order. No images were generated; the script was not shortened.');
const sourceHasTimecodes = /\b\d{1,2}:\d{2}(?::\d{2})?\b/.test(request.script);
const formatTime = seconds => String(Math.floor(seconds / 60)).padStart(2, '0') + ':' + String(seconds % 60).padStart(2, '0');
let elapsedSeconds = 0;
const scenes = plan.scenes.map((scene, index) => {
 const item = scene || {};
 const duration = Math.max(1, Math.ceil(tokens(item.voiceover).length * 60 / 145));
 const timestamp = sourceHasTimecodes ? String(item.timestamp || '').trim() : formatTime(elapsedSeconds) + '-' + formatTime(elapsedSeconds + duration);
 elapsedSeconds += duration;
 return { ...item, sceneNumber: index + 1, timestamp };
});
const unique = new Map();
for (let index = 0; index < scenes.length; index++) {
 const scene = scenes[index];
 const description = String(scene.background || '').trim();
 if (description.length < 20) return fail('Scene ' + (index + 1) + ' is missing a useful Background description. No images were generated.');
 const key = description.toLowerCase().replace(/\s+/g, ' ');
 if (!unique.has(key)) unique.set(key, { backgroundPrompt: description, sceneNumbers: [] });
 unique.get(key).sceneNumbers.push(index + 1);
}
const all = Array.from(unique.values());
if (!all.length) return fail('No distinct storyboard backgrounds were available for image generation.');
const count = Math.min(9, all.length);
const indices = count === 1 ? [Math.floor((all.length - 1) / 2)] : Array.from({length:count}, (_, slot) => Math.round(slot * (all.length - 1) / (count - 1)));
const selectedBackgrounds = indices.map((candidateIndex, slot) => ({ backgroundId: 'BG' + String(slot + 1).padStart(3, '0'), ...all[candidateIndex] }));
const columns = [['Scene','sceneNumber'],['Timestamp','timestamp'],['Voiceover','voiceover'],["What's happening",'whatsHappening'],['Background','background'],['Hand-drawn characters & props','handDrawnCharactersAndProps'],['On-screen text','onScreenText'],['Transitions/Motion','transitionsMotion']];
const csvCell = value => '"' + String(value ?? '').replace(/"/g,'""') + '"';
const storyboardCsv = [columns.map(([header])=>csvCell(header)).join(','),...scenes.map(scene=>columns.map(([,key])=>csvCell(scene[key])).join(','))].join('\r\n');
return [{json:{
 ok:true,title:request.title,mode:request.mode,corsOrigin:request.corsOrigin,
 totalScenes:scenes.length,totalUniqueBackgrounds:all.length,selectedBackgroundCount:selectedBackgrounds.length,
 deferredBackgrounds:Math.max(0,all.length-selectedBackgrounds.length),scriptWordCount:sourceTokens.length,
 timestampMode:sourceHasTimecodes?'provided':'estimated',storyboardCsv,selectedBackgrounds,backgroundCandidates:all
}}];

const packageData=$input.first().json;
if(!packageData.ok)return[{json:packageData}];
const selected=packageData.selectedBackgrounds;
if(!Array.isArray(selected)||!selected.length)return[{json:{ok:false,statusCode:422,error:'The storyboard did not include usable Background descriptions.',mode:packageData.mode,corsOrigin:packageData.corsOrigin}}];
return selected.map(background=>({json:{...background,requestMode:'batch',corsOrigin:packageData.corsOrigin,totalUniqueBackgrounds:packageData.totalUniqueBackgrounds,selectedBackgroundCount:packageData.selectedBackgroundCount,deferredBackgrounds:packageData.deferredBackgrounds}}));

const storyboard = $('Validate and Package Storyboard').first().json;
const results = $input.all().map(item => item.json);
const images = results.map(result => {
  const providerError = typeof result.error === 'string'
    ? result.error
    : result.error?.message ||
      (typeof result.body?.error === 'string' ? result.body.error : result.body?.error?.message) ||
      result.body?.message || result.message;
  const hasImage = result.ok === true && typeof result.imageData === 'string';
  return {
    backgroundId: result.backgroundId,
    sceneNumbers: Array.isArray(result.sceneNumbers) ? result.sceneNumbers : [],
    backgroundPrompt: result.backgroundPrompt || '',
    ...(hasImage
      ? { imageData: result.imageData, mimeType: result.mimeType || 'image/png' }
      : {
          ok: false,
          error: String(providerError || 'Image generation returned no image. Result fields: ' + Object.keys(result).join(', ')),
          statusCode: result.statusCode || result.body?.statusCode || 502
        })
  };
});
const generatedImageCount = images.filter(image => typeof image.imageData === 'string').length;
const failedImageCount = images.length - generatedImageCount;
return [{ json: {
  ok: true,
  title: storyboard.title,
  corsOrigin: storyboard.corsOrigin,
  storyboardCsv: storyboard.storyboardCsv,
  totalScenes: storyboard.totalScenes,
  generatedImageCount,
  failedImageCount,
  totalUniqueBackgrounds: storyboard.totalUniqueBackgrounds,
  selectedBackgroundCount: images.length,
  deferredBackgrounds: storyboard.deferredBackgrounds,
  images
} }];

const input = $json?.body && typeof $json.body === "object" ? $json.body : ($json || {});
const title = String(input.title || "Storyboard").trim().slice(0, 120);
const backgroundId = String(input.backgroundId || "").trim().toLowerCase().replace(/[^a-z0-9-]/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");
const sceneNumbers = Array.isArray(input.sceneNumbers) ? [...new Set(input.sceneNumbers.map(Number).filter(n => Number.isInteger(n) && n > 0))].sort((a, b) => a - b) : [];
const imageData = String(input.imageData || "");
const match = /^data:(image\/(?:png|jpe?g|webp));base64,([A-Za-z0-9+/=\r\n]+)$/i.exec(imageData);
if (!backgroundId || sceneNumbers.length === 0 || !match) throw new Error("A valid background image, background ID, and scene numbers are required.");
const mimeType = match[1].toLowerCase().replace("image/jpg", "image/jpeg");
const extension = mimeType === "image/jpeg" ? "jpg" : mimeType.split("/")[1];
const slug = title.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 48) || "storyboard";
const scenePart = sceneNumbers.map(n => String(n).padStart(2, "0")).join("-");
const fileName = new Date().toISOString().slice(0, 10) + "-" + slug + "-" + backgroundId + "-scenes-" + scenePart + "." + extension;
const bytes = Buffer.from(match[2].replace(/\s/g, ""), "base64");
if (!bytes.length || bytes.length > 12 * 1024 * 1024) throw new Error("The image must be between 1 byte and 12 MB.");
const binary = await this.helpers.prepareBinaryData(bytes, fileName, mimeType);
return [{ json: { ok: true, title, fileName, mimeType, backgroundId, sceneNumbers, folderUrl: "https://drive.google.com/drive/folders/153VPM-IBR1T5UIq-TthqtpklyAGwi-UU" }, binary: { data: binary } }];

